mapper.select:
SELECT t.id, t.task_no, t.status, t.initiator_id
FROM inventory_task t WHERE t.id = #{id}
AND 1 = 1AND t.initiator_id = #{departmentId}

mapper.update:
UPDATE inventory_item SET actual_version_id = #{actualVersionId}, actual_status = #{actualStatus},
    difference_type = #{differenceType}, difference_description = #{differenceDescription}, checked_by = #{checkedBy},
    checked_at = CURRENT_TIMESTAMP WHERE id = #{id}
